BEGIN TRANSACTION;
CREATE TABLE players (
                LP BIGSERIAL PRIMARY KEY,
                Season INTEGER,
                Round INTEGER,
                ID INTEGER,
                Name STRING,
                TeamID INTEGER,
                Age INTEGER,
                Country INTEGER,
                Value INTEGER,
                Salary INTEGER,
                Price INTEGER,
                EndOfSale STRING,
                Matches INTEGER,
                Goals INTEGER,
                Assists INTEGER,
                Stamina INTEGER,
                Speed INTEGER,
                Technique INTEGER,
                Passing INTEGER,
                GK INTEGER,
                DEF INTEGER,
                MID INTEGER,
                ATT INTEGER
            );
COMMIT;
